      title: `Expiry ${s.expiry < 1 ? Math.round(s.expiry * 12 * 10) / 10 + " months" : "1 year"}`,
      sub: `SVI fit RMSE ${s.fit_rmse_variance.toExponential(1)} | min butterfly density ${s.min_butterfly_density.toFixed(2)} (positive = no arbitrage)`,
      delay: i,
